#!/usr/bin/env node
/**
 * Validate `manifest/server-manifest.json` before it is trusted.
 *
 * The manifest is the authority on what to download and which checksum to
 * expect, so a mistake in it is a mistake in a security decision. Generated by
 * `scripts/gen-manifest.mjs` and hand-edited only rarely — which is exactly when
 * this check earns its keep:
 *
 *   * the schema version is one we know how to interpret;
 *   * every `channel.stable[platform]` names a version that exists, ships an
 *     asset for that platform, and can actually be downloaded **with a
 *     checksum** — the asset picked here is the one `resolveAsset()` will pick at
 *     run time, so "default target is unverifiable" is an error, not a note:
 *     it means the install button fails for that platform 100% of the time
 *     (upstream v1.2.19's Windows zip has no `.sha256` sidecar, and that is
 *     exactly how 0.3.3 shipped a Windows install nobody could complete);
 *   * no URL uses a scheme other than https;
 *   * `pluginCompat.minSupportedServer` is a version that exists.
 *
 * Exit code 1 on any problem, so `npm run build` (which calls this) fails rather
 * than shipping a manifest that would download the wrong file — or none at all.
 *
 * Usage:
 *   node scripts/verify-manifest.mjs [path-to-manifest]
 *
 * The optional path is for inspecting a *historical* manifest (a released npm
 * package, a profile's installed copy) with the current rules — that is how the
 * regression behind 0.3.3 was reproduced.
 */

import { readFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import { validateManifest } from './manifest-rules.mjs'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const manifestPath =
  process.argv[2] === undefined ? join(root, 'manifest', 'server-manifest.json') : resolve(process.argv[2])

let manifest
try {
  manifest = JSON.parse(readFileSync(manifestPath, 'utf8'))
} catch (error) {
  console.error(`无法读取 ${manifestPath}：${error.message}`)
  process.exit(1)
}

const { problems, warnings, versions } = validateManifest(manifest)

for (const line of warnings) console.log(`  warn  ${line}`)
if (problems.length > 0) {
  for (const line of problems) console.error(`  error ${line}`)
  console.error(`清单校验失败 (${manifestPath})：${problems.length} 个错误，${warnings.length} 个警告`)
  process.exit(1)
}
console.log(
  `  清单 ok (${manifestPath})：${versions.length} 个版本（${versions[0]} … ${versions.at(-1)}），${warnings.length} 个警告`,
)
